public long[] multiply(int[] a, int[] b) {
    long[] c = new long[a.length + b.length - 1];
    for (int i = 0; i < a.length; i++) {
        for (int j = 0; j < b.length; j++) {
            c[i + j] += (long) a[i] * b[j]; // 64-bit accumulate
        }
    }
    return c;
}

