import java.util.*;

public long[] multiply(int[] a, int[] b) {
    int need = a.length + b.length - 1;
    int n = Integer.highestOneBit(need - 1) << 1; // next power of two >= need
    if (n < need) n <<= 1;
    double[] re1 = new double[n], im1 = new double[n];
    double[] re2 = new double[n], im2 = new double[n];
    for (int i = 0; i < a.length; i++) re1[i] = a[i];
    for (int i = 0; i < b.length; i++) re2[i] = b[i];
    fft(re1, im1, false);
    fft(re2, im2, false);
    for (int i = 0; i < n; i++) {           // pointwise complex multiply
        double r = re1[i] * re2[i] - im1[i] * im2[i];
        double im = re1[i] * im2[i] + im1[i] * re2[i];
        re1[i] = r; im1[i] = im;
    }
    fft(re1, im1, true);                    // inverse FFT (divides by n inside)
    long[] c = new long[need];
    for (int i = 0; i < need; i++) c[i] = Math.round(re1[i]);
    return c;
}

// Iterative radix-2 Cooley-Tukey. invert=true does the inverse transform.
private void fft(double[] re, double[] im, boolean invert) {
    int n = re.length;
    for (int i = 1, j = 0; i < n; i++) {    // bit-reversal permutation
        int bit = n >> 1;
        for (; (j & bit) != 0; bit >>= 1) j ^= bit;
        j ^= bit;
        if (i < j) { double t;
            t = re[i]; re[i] = re[j]; re[j] = t;
            t = im[i]; im[i] = im[j]; im[j] = t;
        }
    }
    for (int len = 2; len <= n; len <<= 1) {
        double ang = 2 * Math.PI / len * (invert ? -1 : 1);
        double wr = Math.cos(ang), wi = Math.sin(ang);
        for (int i = 0; i < n; i += len) {
            double cr = 1, ci = 0;
            for (int k = 0; k < len / 2; k++) {
                int u = i + k, v = i + k + len / 2;
                double vr = re[v] * cr - im[v] * ci;
                double vi = re[v] * ci + im[v] * cr;
                re[v] = re[u] - vr; im[v] = im[u] - vi;
                re[u] += vr; im[u] += vi;
                double ncr = cr * wr - ci * wi; // advance twiddle factor
                ci = cr * wi + ci * wr; cr = ncr;
            }
        }
    }
    if (invert) {
        for (int i = 0; i < n; i++) { re[i] /= n; im[i] /= n; } // the 1/N
    }
}
